import React, { useState } from "react";

const prompts = [
  { key: "name", label: "What is your goal called?" },
  { key: "amount", label: "How much do you want to save? ($)" },
  { key: "deadline", label: "By what date do you want to reach this goal?" },
  { key: "priority", label: "What is the priority for this goal? (1 = highest)" },
];

const GoalWizard = ({ onAddGoal, onClose }) => {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState({ name: "", amount: "", deadline: "", priority: 1 });
  const [touched, setTouched] = useState([false, false, false, false]);

  const handleInput = (e) => {
    const { value } = e.target;
    setValues((prev) => ({ ...prev, [prompts[step].key]: value }));
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (step < prompts.length - 1) {
        setTouched((prev) => prev.map((t, i) => (i === step ? true : t)));
        setStep(step + 1);
      } else {
        handleSubmit();
      }
    }
  };

  const handlePrev = () => {
    if (step > 0) setStep(step - 1);
  };

  const handleNext = () => {
    if (step < prompts.length - 1) setStep(step + 1);
  };

  const handleSubmit = () => {
    if (!values.name || !values.amount || !values.deadline) return;
    onAddGoal({
      id: Date.now().toString(),
      name: values.name,
      amount: parseFloat(values.amount),
      deadline: values.deadline,
      saved: 0,
      priority: Number(values.priority),
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-30 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl shadow-lg p-8 w-full max-w-md flex flex-col items-center">
        <button className="self-end text-gray-400 hover:text-red-500 mb-2" onClick={onClose}>&times;</button>
        <div className="mb-6 w-full text-center">
          <div className="text-2xl font-google font-semibold text-gray-800 mb-2">{prompts[step].label}</div>
        </div>
        <input
          className="w-full border rounded-full px-4 py-3 text-lg shadow focus:outline-none focus:ring-2 focus:ring-primary mb-4 font-google"
          type={prompts[step].key === "amount" ? "number" : prompts[step].key === "deadline" ? "date" : "text"}
          value={values[prompts[step].key]}
          onChange={handleInput}
          onKeyDown={handleKeyDown}
          autoFocus
        />
        <div className="flex justify-between w-full mt-2">
          <button
            className="px-4 py-2 rounded bg-gray-100 text-gray-700 font-medium"
            onClick={handlePrev}
            disabled={step === 0}
          >
            Back
          </button>
          {step < prompts.length - 1 ? (
            <button
              className="px-4 py-2 rounded bg-primary text-white font-semibold"
              onClick={handleNext}
            >
              Next
            </button>
          ) : (
            <button
              className="px-4 py-2 rounded bg-emerald-500 text-white font-semibold"
              onClick={handleSubmit}
            >
              Add Goal
            </button>
          )}
        </div>
        <div className="flex gap-2 mt-4">
          {prompts.map((p, i) => (
            <div
              key={p.key}
              className={`w-3 h-3 rounded-full ${i === step ? "bg-primary" : "bg-gray-200"}`}
            ></div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default GoalWizard;
